import math
X=0.0;Y=0.0;H=0.0
MAP={}
mode='rev';fwd_d=0.0;last_h=None;woke=False;lastp=-10
def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def cl(x,a):
    return max(-a,min(a,x))
def control(obs):
    global X,Y,H,mode,fwd_d,last_h,woke,lastp
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    H+=v*math.tan(st)/2.5*dt;X+=v*math.cos(H)*dt;Y+=v*math.sin(H)*dt
    c=math.cos(H);s=math.sin(H)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0]);ox,oy=o[0],o[1]
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            if d>22: continue
            br=math.radians(b);px=ox+d*math.cos(br);py=oy+d*math.sin(br)
            wx=X+c*px-s*py;wy=Y+s*px+c*py
            MAP[(round(wx/0.3),round(wy/0.3))]=(wx,wy)
    if len(MAP)>4000:
        for k in list(MAP.keys()):
            p=MAP[k]
            if (p[0]-X)**2+(p[1]-Y)**2>900: del MAP[k]
    hitch=obs['hitch_deg'];rig=obs['rig'];tr=rig['trailer_rear']
    Rx=X+c*tr[0]-s*tr[1];Ry=Y+s*tr[0]+c*tr[1]
    beta=H+math.radians(rig['trailer_heading_deg']+180)
    dh=0.0 if last_h is None else (hitch-last_h)/dt
    last_h=hitch
    t=obs['t']
    if t<0.9 or (not obs['head'].get('settled',True) and t<2):
        return (0.0,0.0,170)
    if mode=='fwd':
        fwd_d+=abs(v)*dt
        if abs(hitch)<6 or fwd_d>4.0:
            mode='rev'
        else:
            return (cl(-0.6*hitch,45),1.0,170)
    if abs(hitch)>48:
        mode='fwd';fwd_d=0.0
        wake('hitch %.0f: pulling forward to straighten'%hitch)
        return (cl(-0.6*hitch,45),1.0,170)
    pts=[]
    for p in MAP.values():
        dx=p[0]-Rx;dy=p[1]-Ry
        if dx*dx+dy*dy<196: pts.append((dx,dy))
    Fmax=10.0;C=1.6
    ths=[];fs=[]
    for k in range(-20,21):
        th=beta+math.radians(2.5*k);cb=math.cos(th);sb=math.sin(th);f=Fmax
        for dx,dy in pts:
            sa=dx*cb+dy*sb
            if sa<=0 or sa>=f: continue
            if abs(-dx*sb+dy*cb)<C: f=sa
        ths.append(th);fs.append(f)
    best=max(fs)
    thr=best-0.6
    runs=[];cur=None
    for i,f in enumerate(fs):
        if f>=thr:
            if cur is None: cur=[i,i]
            else: cur[1]=i
        else:
            if cur: runs.append(cur);cur=None
    if cur: runs.append(cur)
    if len(pts)<5 or not runs:
        thg=beta
    else:
        r=max(runs,key=lambda r:(r[1]-r[0])-0.01*abs((r[0]+r[1])/2-20))
        thg=beta+math.radians(2.5*((r[0]+r[1])/2.0-20))
    cb=math.cos(beta);sb=math.sin(beta);dL=3.0;dR=3.0
    for dx,dy in pts:
        sa=dx*cb+dy*sb
        if -5<sa<1:
            la=-dx*sb+dy*cb
            if la>0: dL=min(dL,la)
            else: dR=min(dR,-la)
    corr=cl(5.0*(dL-dR),12)
    e=math.degrees(wrap(thg-beta))+corr
    phid=cl(-1.3*e,32)
    steer=cl(0.5*phid+3.0*(hitch-phid)+cl(0.4*dh,15),45)
    f0=fs[20]
    sp=-1.0
    if abs(hitch-phid)>10 or best<4: sp=-0.6
    if f0<0.5 and len(pts)>20:
        sp=0.0
        if not woke:
            woke=True;wake('rail close behind trailer, stopped')
    if t-lastp>2:
        lastp=t
        print('t%.0f h%.0f pd%.0f e%.0f best%.1f f0%.1f L%.1f R%.1f n%d'%(t,hitch,phid,e,best,f0,dL,dR,len(pts)))
    return (steer,sp,170)

