import math
phase='fwd'
fd=0.0
n=0
last_e=None
def clip(x,a):
    return max(-a,min(a,x))
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def control(obs):
    global phase,fd,n,last_e
    n+=1
    h=obs['hitch_deg']; rig=obs['rig']
    rx,ry=rig['trailer_rear']
    back=rig['trailer_heading_deg']+180.0
    rem=obs['progress']['remaining']
    v=obs['motion']['v_mps']
    st=obs.get('status')
    tg=obs.get('target') or {}
    e=None; dist=None
    if tg.get('in_sight') and tg.get('bearing_deg') is not None:
        ex,ey=rig['eye']
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        px=ex+d*math.cos(b); py=ey+d*math.sin(b)
        dist=math.hypot(px-rx,py-ry)
        e=wrap(math.degrees(math.atan2(py-ry,px-rx))-back)
        if dist<1.0: e=0.0
        last_e=e
    look=clip(wrap(back),170)
    if abs(look)<100: look=170 if look>=0 else -170
    if phase=='rev' and (abs(h)>38 or (st=='PINNED' and obs['motion']['hold_s']<=0.05)):
        phase='fwd'; fd=0.0
    if phase=='fwd':
        if v>0: fd+=v*obs['dt']
        if (fd>0.9 and abs(h)<8) or fd>2.0:
            phase='rev'
        else:
            if n%10==0: print('FWD t%.1f fd%.2f h%.1f'%(obs['t'],fd,h))
            return (clip(-1.3*h,35),0.6,look)
    if e is None: e=last_e if last_e is not None else 0.0
    des=clip(-1.0*e,22)
    if rem<1.2: des=clip(des,6)
    steer=clip(2.5*(h-des),45)
    sp=-0.5 if rem>2 else -0.35
    if n%15==0: print('t%.1f rem%.2f h%.1f e%s dist%s des%.1f st%s'%(obs['t'],rem,h,None if e is None else round(e,1),None if dist is None else round(dist,2),des,st))
    return (steer,sp,look)

